# Verify the computation for the top gene
import os
from collections import Counter

def is_gap_char(c):
    return c in ('-', '.', '?', 'X', '*')

def read_fasta_records(filepath):
    records = []
    current_header = None
    current_seq = []
    with open(filepath, 'r') as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            if line.startswith('>'):
                if current_header is not None:
                    records.append((current_header, ''.join(current_seq)))
                current_header = line[1:]
                current_seq = []
            else:
                current_seq.append(line)
        if current_header is not None:
            records.append((current_header, ''.join(current_seq)))
    return records

# Check the top gene
top_gene = '1428854at2759.faa.mafft'
path = os.path.join('/workspace/mafft_alignments', top_gene)

records = read_fasta_records(path)
print(f"Gene: {top_gene}")
print(f"Number of sequences: {len(records)}")
for header, seq in records:
    print(f"  {header}: len={len(seq)}")

sequences = [seq for _, seq in records]

n_seqs = len(sequences)
seq_len = len(sequences[0])

# Check lengths
for s in sequences:
    if len(s) != seq_len:
        print(f"  LENGTH MISMATCH: {seq_len} vs {len(s)}")

informative = 0
for col in range(seq_len):
    aa_counts = Counter()
    for seq_idx in range(n_seqs):
        aa = sequences[seq_idx][col].upper()
        if not is_gap_char(aa):
            aa_counts[aa] += 1
    qualifying = [c for c in aa_counts.values() if c >= 2]
    if len(qualifying) >= 2:
        informative += 1

print(f"\nTotal sites: {seq_len}")
print(f"Parsimony informative: {informative}")
print(f"Percentage: {informative/seq_len*100:.4f}%")

# Also verify a few others
for gene in ['570797at2759.faa.mafft', '341721at2759.faa.mafft']:
    path = os.path.join('/workspace/mafft_alignments', gene)
    if os.path.exists(path):
        records = read_fasta_records(path)
        sequences = [seq for _, seq in records]
        n_seqs = len(sequences)
        seq_len = len(sequences[0])
        informative = 0
        for col in range(seq_len):
            aa_counts = Counter()
            for seq_idx in range(n_seqs):
                aa = sequences[seq_idx][col].upper()
                if not is_gap_char(aa):
                    aa_counts[aa] += 1
            qualifying = [c for c in aa_counts.values() if c >= 2]
            if len(qualifying) >= 2:
                informative += 1
        print(f"\n{gene}: {informative}/{seq_len} = {informative/seq_len*100:.4f}%")
